# Problem: binpacking

Write a function `pack(items: list[int], capacity: int) -> list[int]`.

- `items` are the item sizes, each between 1 and `capacity`, in arrival order.
- Return a list with one bin number per item (same length and order as `items`); bin
  numbers are any non-negative integers, items with the same number share a bin.
- The total size in every bin must not exceed `capacity`.
- Goal: use as few bins as possible. Score = reference / bins used (1.0 is optimal).
- Standard library only (no numpy), at most 2 seconds per call, no files or network.
- An invalid answer (wrong length, overfull bin, exception, timeout) scores 0.

## Candidate `g2-llm01`

```python
"""Greedy construction (BFD and minimum-bin-slack look-ahead) followed by a
local search: bin elimination with load-increasing swaps, wrapped in a
ruin-and-recreate loop until the deadline or the lower bound is reached."""
import sys
import time
import random
from bisect import bisect_left, bisect_right, insort


def _lower_bound(items, cap):
    n = len(items)
    a = sorted(items)
    pre = [0]
    for s in a:
        pre.append(pre[-1] + s)
    total = pre[-1]
    best = max(1, -(-total // cap))
    half = cap // 2
    i_half = bisect_right(a, half)
    best = max(best, n - i_half)
    ks = sorted(set(a[:i_half]))
    if len(ks) > 400:
        step = len(ks) / 400.0
        ks = [ks[int(j * step)] for j in range(400)]
    for k in ks:
        i1 = bisect_right(a, cap - k)
        n1 = n - i1
        n2 = i1 - i_half if i1 > i_half else 0
        s2 = pre[i1] - pre[i_half] if i1 > i_half else 0
        ik = bisect_left(a, k)
        s3 = pre[i_half] - pre[ik]
        extra = s3 - (n2 * cap - s2)
        L = n1 + n2 + (-(-extra // cap) if extra > 0 else 0)
        if L > best:
            best = L
    return best


def _bfd_bins(items, cap, order, bins=None):
    if bins is None:
        bins = []
    rooms = []
    for b, lst in enumerate(bins):
        room = cap - sum(items[i] for i in lst)
        if room > 0:
            rooms.append((room, b))
    rooms.sort()
    for i in order:
        s = items[i]
        k = bisect_left(rooms, (s, -1))
        if k < len(rooms):
            room, b = rooms.pop(k)
            bins[b].append(i)
            room -= s
        else:
            b = len(bins)
            bins.append([i])
            room = cap - s
        if room > 0:
            insort(rooms, (room, b))
    return bins


def _mbs(items, cap, idx, deadline, node_limit):
    by_size = {}
    for i in idx:
        by_size.setdefault(items[i], []).append(i)
    sizes = sorted(by_size, reverse=True)
    m = len(sizes)
    counts = [len(by_size[s]) for s in sizes]
    neg = [-s for s in sizes]
    best_room = [0]
    best_set = [[]]
    chosen = []
    budget = [0]

    def dfs(start, room):
        j = bisect_left(neg, -room)
        if j < start:
            j = start
        while j < m:
            if budget[0] <= 0:
                return True
            budget[0] -= 1
            if counts[j]:
                counts[j] -= 1
                chosen.append(j)
                r = room - sizes[j]
                if r < best_room[0]:
                    best_room[0] = r
                    best_set[0] = chosen[:]
                if r == 0:
                    stop = True
                else:
                    stop = dfs(j, r)
                chosen.pop()
                counts[j] += 1
                if stop:
                    return True
            j += 1
        return False

    bins = []
    remaining = len(idx)
    top = 0
    while remaining:
        while counts[top] == 0:
            top += 1
        if time.perf_counter() > deadline:
            rest = []
            for j in range(m):
                rest.extend(by_size[sizes[j]])
            return _bfd_bins(items, cap, rest, bins)
        counts[top] -= 1
        first = by_size[sizes[top]].pop()
        room0 = cap - sizes[top]
        best_room[0] = room0
        best_set[0] = []
        budget[0] = node_limit
        if room0 > 0:
            dfs(0, room0)
        b = [first]
        for j in best_set[0]:
            counts[j] -= 1
            b.append(by_size[sizes[j]].pop())
        bins.append(b)
        remaining -= len(b)
    return bins


def _best_swap(items, cap, nb, nl, pool):
    p = len(pool)
    popts = [(items[pool[a]], (a,)) for a in range(p)]
    if p <= 25:
        for a in range(p):
            sa = items[pool[a]]
            for c in range(a + 1, p):
                popts.append((sa + items[pool[c]], (a, c)))
    popts.sort(key=lambda x: x[0])
    pvals = [x[0] for x in popts]
    best_gain = 0
    best = None
    for k in range(len(nb)):
        slack = cap - nl[k]
        B = nb[k]
        L = len(B)
        pairs = L <= 20
        for x in range(L):
            sx = items[B[x]]
            j = bisect_right(pvals, sx + slack) - 1
            if j >= 0:
                g = pvals[j] - sx
                if g > best_gain:
                    best_gain = g
                    best = (k, (x,), popts[j][1])
            if pairs:
                for y in range(x + 1, L):
                    r = sx + items[B[y]]
                    j = bisect_right(pvals, r + slack) - 1
                    if j >= 0:
                        g = pvals[j] - r
                        if g > best_gain:
                            best_gain = g
                            best = (k, (x, y), popts[j][1])
    return best


def _try_empty(items, cap, bins, loads, t, deadline, max_steps):
    nb = [bins[k][:] for k in range(len(bins)) if k != t]
    nl = [loads[k] for k in range(len(bins)) if k != t]
    pool = list(bins[t])
    nbin = len(nb)
    for _ in range(max_steps):
        pool.sort(key=lambda i: -items[i])
        rest = []
        for i in pool:
            s = items[i]
            lim = cap - s
            bb = -1
            bl = -1
            for k in range(nbin):
                l = nl[k]
                if bl < l <= lim:
                    bl = l
                    bb = k
                    if l == lim:
                        break
            if bb >= 0:
                nb[bb].append(i)
                nl[bb] += s
            else:
                rest.append(i)
        pool = rest
        if not pool:
            return nb, nl
        if len(pool) > 40 or time.perf_counter() > deadline:
            return None
        mv = _best_swap(items, cap, nb, nl, pool)
        if mv is None:
            return None
        k, rem, add = mv
        B = nb[k]
        removed = [B[x] for x in rem]
        for x in sorted(rem, reverse=True):
            B.pop(x)
        addset = set(add)
        added = [pool[a] for a in add]
        B.extend(added)
        nl[k] += sum(items[i] for i in added) - sum(items[i] for i in removed)
        pool = [pool[a] for a in range(len(pool)) if a not in addset] + removed
    return None


def _improve(items, cap, bins, lb, deadline, max_targets, max_steps):
    bins = [b[:] for b in bins]
    loads = [sum(items[i] for i in b) for b in bins]
    while len(bins) > lb:
        if time.perf_counter() > deadline:
            break
        order = sorted(range(len(bins)), key=lambda k: (loads[k], len(bins[k])))
        done = False
        for t in order[:max_targets]:
            if time.perf_counter() > deadline:
                break
            res = _try_empty(items, cap, bins, loads, t, deadline, max_steps)
            if res is not None:
                bins, loads = res
                done = True
                break
        if not done:
            break
    return bins


def _key(items, bins):
    sq = 0
    for b in bins:
        l = 0
        for i in b:
            l += items[i]
        sq += l * l
    return (len(bins), -sq)


def _ruin_recreate(items, cap, bins, rng, nkill, deadline):
    nbins = len(bins)
    loads = [sum(items[i] for i in b) for b in bins]
    light = sorted(range(nbins), key=lambda k: loads[k])
    nkill = min(nbins, nkill)
    kill = set(light[:max(1, nkill // 2)])
    while len(kill) < nkill:
        kill.add(rng.randrange(nbins))
    keep = [bins[k][:] for k in range(nbins) if k not in kill]
    freed = [i for k in kill for i in bins[k]]
    if rng.random() < 0.5:
        rng.shuffle(freed)
        noise = rng.choice((0.0, 0.05, 0.15))
        freed.sort(key=lambda i: -items[i] * (1.0 + noise * rng.random()))
        return _bfd_bins(items, cap, freed, keep)
    sub = _mbs(items, cap, freed, deadline, 3000)
    return keep + sub


def _assign(bins, n):
    a = [-1] * n
    for b, lst in enumerate(bins):
        for i in lst:
            a[i] = b
    return a


def _valid(items, cap, a):
    if len(a) != len(items):
        return False
    loads = {}
    for i, b in enumerate(a):
        if b < 0:
            return False
        loads[b] = loads.get(b, 0) + items[i]
    for v in loads.values():
        if v > cap:
            return False
    return True


def pack(items, capacity):
    n = len(items)
    if n == 0:
        return []
    t0 = time.perf_counter()
    hard = t0 + 1.55
    cap = capacity
    try:
        if sys.getrecursionlimit() < 20000:
            sys.setrecursionlimit(20000)
    except Exception:
        pass
    order = sorted(range(n), key=lambda i: -items[i])
    best = _bfd_bins(items, cap, order)
    fallback = _assign(best, n)
    try:
        lb = _lower_bound(items, cap)
        if len(best) > lb:
            node_limit = max(300, min(40000, 1500000 // max(1, lb)))
            try:
                m = _mbs(items, cap, list(range(n)), t0 + 0.55, node_limit)
                if _key(items, m) < _key(items, best):
                    best = m
            except RecursionError:
                pass
        if len(best) > lb:
            best = _improve(items, cap, best, lb, hard, 40, 60)
        rng = random.Random(n * 104729 + cap)
        cur = best
        cur_key = _key(items, cur)
        while len(best) > lb and time.perf_counter() < hard:
            frac = rng.choice((0.03, 0.08, 0.15, 0.25))
            nk = max(2, int(len(cur) * frac) + 1)
            try:
                cand = _ruin_recreate(items, cap, cur, rng, nk, hard)
            except RecursionError:
                continue
            cand = _improve(items, cap, cand, lb, hard, 5, 30)
            ck = _key(items, cand)
            if ck <= cur_key or (ck[0] == cur_key[0] and rng.random() < 0.03):
                cur, cur_key = cand, ck
            if len(cand) < len(best):
                best = cand
        result = _assign(best, n)
        if _valid(items, cap, result):
            return result
    except Exception:
        pass
    return fallback
